// signup.test.js: Vitest + @testing-library/dom + user-event, jsdom environment.
import { it, expect, vi } from "vitest";
import { screen } from "@testing-library/dom";
import userEvent from "@testing-library/user-event";
import { mountSignup } from "./signup.js";

it("shows success after a valid sign-up", async () => {
  const fakeFetch = vi.fn().mockResolvedValue(new Response("{}", { status: 201 }));
  mountSignup(document.body, { fetch: fakeFetch });       // dependency injected.
  const user = userEvent.setup();

  await user.type(screen.getByLabelText("Email"), "asha@example.com");
  await user.click(screen.getByRole("button", { name: "Join" }));

  expect(await screen.findByText("Account created.")).toBeTruthy();
  expect(fakeFetch).toHaveBeenCalledTimes(1);
});

it("announces a server error", async () => {
  const fakeFetch = vi.fn().mockResolvedValue(new Response("", { status: 500 }));
  mountSignup(document.body, { fetch: fakeFetch });
  const user = userEvent.setup();
  await user.type(screen.getByLabelText("Email"), "asha@example.com");
  await user.keyboard("{Enter}");                        // keyboard submission too.
  expect(await screen.findByText(/try again/i)).toBeTruthy();
});
```

| Prefer | Avoid |
|---|---|
| getByRole, getByLabelText, getByText. | class names, test-only ids everywhere. |
| user.type, user.click, keyboard. | calling handlers directly. |
| findBy (waits). | fixed sleeps. |
| fake fetch per test. | real network. |

